page_settings.custom_css:
/* Only form fields, runtime filter state and mobile dialog behaviour.
   All section/card layout, colours, typography, spacing and radius use native Elementor controls. */
:where(.elementor-1278){--jsp-blue:#236b9c;--jsp-navy:#122e43;--jsp-ink:#223747;--jsp-muted:#657783;--jsp-line:#e1eaf0;--jsp-radius:12px}
:where(.elementor-1278) [hidden][hidden]{display:none}
:where(.elementor-1278 .elementor-widget-text-editor p){margin:0}
:where(.elementor-1278 .jsp-product-photo img){display:block;mix-blend-mode:multiply}
:where(.elementor-1278 .jsp-sr-only){position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap}
:where(.elementor-1278 .jsp-sort select){min-height:40px;max-width:195px;padding:8px 30px 8px 13px;border:1px solid #e1eaf0;border-radius:12px;color:#657783;background:white;font:11px/1.5 'Segoe UI',sans-serif;cursor:pointer}
:where(.elementor-1278 .jsp-filter-options){display:flex;flex-wrap:wrap;gap:7px;margin-top:13px}
:where(.elementor-1278 .jsp-filter-options label){position:relative;cursor:pointer;margin:0;line-height:1.6}
:where(.elementor-1278 .jsp-filter-options input){position:absolute;width:1px;height:1px;opacity:0;margin:0}
:where(.elementor-1278 .jsp-filter-options label>span){display:block;min-width:37px;border:1px solid #dae5ed;background:white;border-radius:12px;padding:8px 10px;font:10px/1.6 'Segoe UI',sans-serif;text-align:center;color:#617b8e;transition:background .15s,color .15s}
:where(.elementor-1278 .jsp-filter-options label:hover>span){border-color:#9cbdd3;color:#236b9c}
:where(.elementor-1278 .jsp-filter-options input:checked+span){background:#122e43;border-color:#122e43;color:white}
:where(.elementor-1278 .jsp-filter-options input:focus-visible+span){outline:3px solid #236b9c;outline-offset:3px}
:where(.elementor-1278 .jsp-number-options){display:grid;grid-template-columns:repeat(4,minmax(0,1fr))}
:where(.elementor-1278 .jsp-number-options label>span){min-width:0;padding-inline:3px}
:where(.elementor-1278 .jsp-price-inputs){display:grid;grid-template-columns:1fr auto 1fr;align-items:end;gap:8px;margin-top:13px}
:where(.elementor-1278 .jsp-price-inputs label>span){display:block;font:9px/1.5 'Segoe UI',sans-serif;color:#8a9ba7;margin-bottom:6px}
:where(.elementor-1278 .jsp-price-inputs input){width:100%;min-width:0;height:38px;padding:8px 9px;font:11px/1.5 'Segoe UI',sans-serif;border:1px solid #dae5ed;border-radius:12px;color:#223747;background:white;box-shadow:none}
:where(.elementor-1278 .jsp-price-inputs>span){line-height:38px;color:#8a9ba7}
:where(.elementor-1278 .jsp-price-inputs~small){display:block;font:9px/1.8 'Segoe UI',sans-serif;color:#8b9da9;margin-top:9px}
:where(.elementor-1278 .jsp-price-error){font:10px/1.8 'Segoe UI',sans-serif;color:#a03c35;margin:10px 0 0}
:where(.elementor-1278 .jsp-active-filters button){display:inline-flex;align-items:center;gap:8px;border:1px solid #d9e8f3;border-radius:12px;padding:6px 10px;background:#f0f7fc;color:#236b9c;font:10px/1.5 'Segoe UI',sans-serif;cursor:pointer}
:where(.elementor-1278 .jsp-active-filters svg){width:12px;height:12px}
:where(.elementor-1278 .jsp-native-dialog){position:fixed;inset:0 0 0 auto;width:min(90vw,380px);height:100dvh;max-height:none;max-width:none;margin:0;padding:0;border:0;border-radius:12px 0 0 12px;background:transparent;overflow:auto;overscroll-behavior:contain}
:where(.elementor-1278 .jsp-native-dialog::backdrop){background:#071c2f80;backdrop-filter:blur(3px)}
body.elementor-page-1278 .site-main{max-width:none;margin:0;padding:0}
body.elementor-page-1278 .entry-content{margin:0}
@media(max-width:767px){
 :where(.elementor-1278 .jsp-filter-options label>span){font-size:12px;padding:10px 12px}
 :where(.elementor-1278 .jsp-number-options){grid-template-columns:repeat(5,minmax(0,1fr))}
 :where(.elementor-1278 .jsp-number-options label>span){padding-inline:2px}
 :where(.elementor-1278 .jsp-price-inputs input){height:43px;font-size:12px}
 :where(.elementor-1278 .jsp-sort select){min-height:42px;max-width:190px}
}
@media(prefers-reduced-motion:reduce){:where(.elementor-1278 .jsp-filter-options label>span){transition:none}}
